import std.io

pub type AppError = Failed(String)

fn pair() -> (Int64, String) {
    return (7, "seven")
}

fn sum(p: (Int64, Int64)) -> Int64 {
    let (lo, hi) = p
    return lo + hi
}

pub fn main() effect io -> Result<(), AppError> {
    let (a, b) = pair()
    io.println("${a} ${b}")
    let box = (3, 4)
    io.println("${sum(box)} ${sum((10, 20))}")
    let (x, y) = (5, 6)
    io.println("${x + y}")
    return Ok(())
}
